            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            margin: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
        }

        #root {
            width: 100%;
            max-width: 600px;
            padding: 20px;
        }

        .quiz-container {
            background-color: var(--surface-color);
            padding: 2rem;
            border-radius: 12px;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
        }

        h1 {
            text-align: center;
            color: var(--primary-color);
            margin-bottom: 2rem;
        }

        .form-field {
            margin-bottom: 2rem;
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 1.5rem;
        }

        .form-field:last-of-type {
            border-bottom: none;
        }

        .question-label {
            display: block;
            font-size: 1.2rem;
            font-weight: 600;
            margin-bottom: 0.5rem;
        }

        .help-text {
            display: block;
            font-size: 0.9rem;
            color: var(--text-muted);
            margin-bottom: 1rem;
            font-style: italic;
        }

        .options-group {
            display: flex;
            flex-direction: column;
            gap: 0.8rem;
        }

        .option-item {
            display: flex;
            align-items: center;
            cursor: pointer;
            padding: 8px;
            border-radius: 6px;
            transition: background-color 0.2s;
        }

        .option-item:hover {
            background-color: rgba(255, 255, 255, 0.05);
        }

        .option-item input[type="checkbox"] {
            appearance: none;
            -webkit-appearance: none;
            width: 20px;
            height: 20px;
            border: 2px solid var(--primary-color);
            border-radius: 4px;
            margin-right: 12px;
            position: relative;
            cursor: pointer;
            outline: none;
        }

        .option-item input[type="checkbox"]:checked {
            background-color: var(--primary-color);
        }

        .option-item input[type="checkbox"]:checked::after {
            content: '✔';
            position: absolute;
            top: 50%;
            left: 50%;
            transform: translate(-50%, -50%);
            color: var(--bg-color);
            font-size: 14px;
        }

        .submit-btn {
            display: block;
            width: 100%;
            padding: 1rem;
            background-color: var(--primary-color);
            color: var(--bg-color);
            border: none;
            border-radius: 6px;
            font-size: 1.1rem;
            font-weight: bold;
            cursor: pointer;
            transition: transform 0.1s, background-color 0.2s;
            margin-top: 1rem;
        }

        .submit-btn:hover {
            background-color: #a370f7;
        }

        .submit-btn:active {
            transform: scale(0.98);
        }

        .results {
            margin-top: 2rem;
            padding: 1rem;
            border: 1px solid var(--secondary-color);
            border-radius: 6px;
            background-color: rgba(3, 218, 198, 0.1);
        }
    </style>
</head>
<body>
    <div id="root"></div>
    <script type="text/babel">
        const { useState } = React;

        const questions = [
          {
            id: 1,
            question: "Which of the following are statically typed languages?",
            helpText: "Statically typed languages perform type checking at compile-time rather than at run-time.",
            options: ["Java", "Python", "C++", "JavaScript"],
            correct: ["Java", "C++"]
          },
          {
            id: 2,
            question: "Which of these languages are commonly used for server-side development?",
            options: ["PHP", "Ruby", "Swift", "Go"],
            correct: ["PHP", "Ruby", "Go"]
          },
          {
            id: 3,
            question: "Which of the following are functional programming languages (or have strong functional features)?",
            options: ["Haskell", "Lisp", "C", "Erlang"],
            correct: ["Haskell", "Lisp", "Erlang"]
          }
        ];

        const CheckboxGroup = ({ options, selectedOptions, onChange }) => {
          return (
            <div className="options-group">
              {options.map((option) => (
                <label key={option} className="option-item">
                  <input
                    type="checkbox"
                    checked={selectedOptions.includes(option)}
                    onChange={() => onChange(option)}
                  />
                  {option}
                </label>
              ))}
            </div>
          );
        };

        const Quiz = () => {
          const [answers, setAnswers] = useState({
            1: [],
            2: [],
            3: []
          });
          const [submitted, setSubmitted] = useState(false);

          const handleCheckboxChange = (questionId, option) => {
            setAnswers((prev) => {
              const currentSelections = prev[questionId];
              if (currentSelections.includes(option)) {
                return { ...prev, [questionId]: currentSelections.filter((o) => o !== option) };
              } else {
                return { ...prev, [questionId]: [...currentSelections, option] };
              }
            });
          };

          const handleSubmit = (e) => {
            e.preventDefault();
            setSubmitted(true);
          };

          const calculateScore = () => {
            let correctCount = 0;
            questions.forEach((q) => {
              const userAnswers = [...answers[q.id]].sort();
              const correctAnswers = [...q.correct].sort();
              if (JSON.stringify(userAnswers) === JSON.stringify(correctAnswers)) {
                correctCount++;
              }
            });
            return correctCount;
          };

          return (
            <div className="quiz-container">
              <h1>CS Languages Quiz</h1>
              <form onSubmit={handleSubmit}>
                {questions.map((q) => (
                  <div key={q.id} className="form-field">
                    <span className="question-label">{q.question}</span>
                    {q.helpText && <span className="help-text">{q.helpText}</span>}
                    <CheckboxGroup
                      options={q.options}
                      selectedOptions={answers[q.id]}
                      onChange={(option) => handleCheckboxChange(q.id, option)}
                    />
                  </div>
                ))}
                <button type="submit" className="submit-btn">Submit Quiz</button>
              </form>
              {submitted && (
                <div className="results">
                  <h2>Results</h2>
                  <p>You got {calculateScore()} out of {questions.length} correct!</p>
                  <button onClick={() => setSubmitted(false)} className="submit-btn" style={{backgroundColor: 'var(--secondary-color)', marginTop: '10px'}}>
                    Try Again
                  </button>
                </div>
              )}
            </div>
          );
        };

        const App = () => {
          return (
            <div className="app">
              <Quiz />
            </div>
          );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
</body>
</html>
