 <!DOCTYPE html>
 <html lang="en">
 <head>
     <meta charset="UTF-8">
     <meta name="viewport" content="width=device-width, initial-scale=1.0">
     <title>Computer Languages Quiz</title>
     <style>
         :root {
             --bg-color: #121212;
             --surface-color: #1e1e1e;
             --primary-color: #bb86fc;
             --secondary-color: #03dac6;
             --text-color: #e0e0e0;
             --text-muted: #a0a0a0;
             --error-color: #cf6679;
             --border-color: #333;
         }

         body {
             background-color: var(--bg-color);
             color: var(--text-color);
             font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
             margin: 0;
             display: flex;
             justify-content: center;
             align-items: center;
             min-height: 100vh;
         }

         #root {
             width: 100%;
             max-width: 600px;
             padding: 20px;
         }

         .quiz-container {
             background-color: var(--surface-color);
             padding: 2rem;
             border-radius: 12px;
             box-shadow: 0 10px 30px rgba(0, 0, 0, 0.5);
         }

         h1 {
             text-align: center;
             color: var(--primary-color);
             margin-bottom: 2rem;
         }

         .form-field {
             margin-bottom: 2rem;
             border-bottom: 1px solid var(--border-color);
             padding-bottom: 1.5rem;
         }

         .form-field:last-of-type {
             border-bottom: none;
         }

         .question-label {
             display: block;
             font-size: 1.2rem;
             font-weight: 600;
             margin-bottom: 0.5rem;
         }

         .help-text {
             display: block;
             font-size: 0.9rem;
             color: var(--text-muted);
             margin-bottom: 1rem;
             font-style: italic;
         }

         .options-group {
             display: flex;
             flex-direction: column;
             gap: 0.8rem;
         }

         .option-item {
             display: flex;
             align-items: center;
             cursor: pointer;
             padding: 8px;
             border-radius: 6px;
             transition: background-color 0.2s;
         }

         .option-item:hover {
             background-color: rgba(255, 255, 255, 0.05);
         }

         .option-item input[type="checkbox"] {
             appearance: none;
             -webkit-appearance: none;
             width: 20px;
             height: 20px;
             border: 2px solid var(--primary-color);
             border-radius: 4px;
             margin-right: 12px;
             position: relative;
             cursor: pointer;
             outline: none;
         }

         .option-item input[type="checkbox"]:checked {
             background-color: var(--primary-color);
         }

         .option-item input[type="checkbox"]:checked::after {
             content: '✔';
             position: absolute;
             top: 50%;
             left: 50%;
             transform: translate(-50%, -50%);
             color: var(--bg-color);
             font-size: 14px;
